<form method="GET" class="distributor-filters" role="search">
    <?php if(!empty($columnFilters['selected'])): ?><input type="hidden" name="columns" value="<?php echo e(json_encode($columnFilters['selected'])); ?>"><?php endif; ?>
    <label class="distributor-search"><?php echo $__env->make('pharmacy-store.distributor.icon', ['icon' => 'search'], array_diff_key(get_defined_vars(), ['__data' => 1, '__path' => 1]))->render(); ?><span class="distributor-sr-only">Buscar producto o presentación</span><input type="search" name="q" value="<?php echo e($filters['q'] ?? ''); ?>" maxlength="200" placeholder="Buscar producto o presentación"></label>
    <label><span class="distributor-sr-only">Existencias</span><select name="stock" aria-label="Existencias"><option value="all">Existencias: todas</option><?php $__currentLoopData = ['available' => 'Con existencias', 'empty' => 'Agotadas', 'low' => 'Existencias bajas (1–5)']; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $key => $label): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option value="<?php echo e($key); ?>" <?php if(($filters['stock'] ?? '') === $key): echo 'selected'; endif; ?>><?php echo e($label); ?></option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select></label>
    <label><span class="distributor-sr-only">Estado</span><select name="status" aria-label="Estado"><option value="all">Estado: todos</option><option value="active" <?php if(($filters['status'] ?? '') === 'active'): echo 'selected'; endif; ?>>Activo</option><option value="inactive" <?php if(($filters['status'] ?? '') === 'inactive'): echo 'selected'; endif; ?>>Inactivo</option></select></label>
    <button class="distributor-button secondary" type="submit">Filtrar</button>
    <?php if(request()->filled('q') || request()->filled('stock') || request()->filled('status')): ?><a class="distributor-reset" href="<?php echo e(url()->current()); ?>">Limpiar</a><?php endif; ?>
</form>
